void main() {
  const int year = 2025;    // compile-time constant
  final String name;        // final: assigned ONCE
  name = 'Alex';

  var hours = 72;           // type inferred (int)
  double score = 4.6;
  bool passed = true;

  print(name);
  print('In $year $name studied $hours hours');
  print('Score: $score. Passed: $passed');
}

