void main() {
  String city = 'Perm';   // non-nullable
  String? nickname;       // String? - may be null
  print(nickname);

  print(city.length);
  nickname = 'Pip';
  print(nickname.length); // flow analysis: now not null

  nickname = null;        // fine for String?
  print(nickname ?? 'none');
}

int safeLength(String? text) {
  return text?.length ?? 0;   // ?. with ?? : null-safe chain
}

void main() {
  print(safeLength(null));
  print(safeLength('Flutter'));
}

int doubleIt(int n) => n * 2;         // arrow syntax: one expression

int power({required int base, int exp = 2}) {
  var result = 1;
  for (var i = 0; i < exp; i++) {
    result *= base;
  }
  return result;
}

void greet(String name, [String? title]) {  // optional positional
  final prefix = title == null ? 'Hello, ' : '$title, ';
  print('$prefix$name');
}

void main() {
  print(doubleIt(21));
  print(power(base: 3));
  print(power(base: 2, exp: 5));

  greet('Anna');
  greet('Anna', 'Dr.');

  final add = (int a, int b) => a + b;      // anonymous function
  print(add(2, 3));
}

Future<String> slowTask(String label, int ms) async {
  await Future.delayed(Duration(milliseconds: ms));
  return '$label done';
}

Future<void> main() async {
  print('start');

  final first = await slowTask('first', 50);
  print(first);

  // Both tasks run concurrently; list is in call order
  final results = await Future.wait([
    slowTask('second', 30),
    slowTask('third', 60),
  ]);
  print(results);

  print('end');
}

Future<int> divide(int a, int b) async {
  await Future.delayed(const Duration(milliseconds: 10));
  if (b == 0) {
    throw Exception('division by zero');
  }
  return a ~/ b;
}

Future<void> main() async {
  print(await divide(10, 2));

  try {
    print(await divide(10, 0));
  } catch (e) {
    print('caught: $e');
  }
  print('after');
}

